<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#222;padding:36px;font-size:13px}.head{border-bottom:3px solid #ff4d8f;padding-bottom:18px}.logo{max-height:48px}h1{color:#ff4d8f;float:right;margin:0}table{width:100%;border-collapse:collapse;margin-top:28px}th,td{padding:12px;border-bottom:1px solid #ddd;text-align:left}.total{text-align:right;font-size:18px;font-weight:bold;margin-top:24px}</style></head><body><div class="head"><img class="logo" src="{{ public_path('img/logo.png') }}" alt="{{ config('company.name') }}"><h1>INVOICE</h1><p>{{ config('company.name') }}<br>{{ config('company.address') }}<br>GSTIN: {{ config('company.gst') }}</p></div><table><tr><th>Bill to</th><th>Plan details</th></tr><tr><td>{{ $subscription->user->name }}<br>{{ $subscription->user->email }}</td><td>{{ $subscription->subscriptionPlan?->name ?? $subscription->model }}<br>Child: {{ $subscription->child?->name }}<br>Valid: {{ $subscription->starts_at?->format('d M Y') }} – {{ $subscription->expires_at?->format('d M Y') }}<br>Payment: {{ strtoupper($subscription->payment_status) }}</td></tr></table><div class="total">Total paid: ₹{{ number_format((float) $subscription->amount_paid, 2) }}</div><p style="margin-top:45px;color:#777">This is a computer-generated invoice and does not require a signature.</p></body></html>
